dosage_model.compute_function:
def compute_dose(base_dose_mid_mg, doses_per_day,
                 age_years, weight_kg, sex,
                 gfr=90.0, child_pugh=5,
                 severity='moderate',
                 is_pregnant=False, is_breastfeeding=False,
                 tables=None):
    """
    Returns dict with single_dose_mg (float) and daily_dose_mg (float).
    All inputs are numbers or short enum strings.
    tables = dosage_model['adjustment_tables']  (injected at call site)
    """
    if base_dose_mid_mg is None:
        return {'computable': False, 'reason': 'no_numeric_base_dose'}

    # 1. Age multiplier
    age_mult = None
    age_max  = None
    for row in tables['age']:
        if row[0] <= age_years < row[1]:
            age_mult, age_max = row[2], row[3]
            break
    if age_mult is None:
        return {'computable': False, 'reason': 'age_requires_specialist'}

    # 2. Severity multiplier
    sev_mult = tables['severity'].get(severity, 1.0)

    # 3. Renal multiplier
    ren_mult = 1.0
    for row in tables['renal']:
        if row[0] <= gfr <= row[1]:
            ren_mult = row[2]
            break
    if ren_mult is None:
        return {'computable': False, 'reason': 'renal_requires_specialist'}

    # 4. Hepatic multiplier
    hep_mult = 1.0
    for row in tables['hepatic']:
        if row[0] <= child_pugh <= row[1]:
            hep_mult = row[2]
            break

    # 5. Gender multiplier
    if is_pregnant:
        gen_mult = tables['gender']['female_pregnant']
    elif is_breastfeeding:
        gen_mult = tables['gender']['female_breastfeeding']
    elif sex == 'female':
        gen_mult = tables['gender']['female_non_pregnant']
    else:
        gen_mult = tables['gender']['male']
    if gen_mult is None:
        return {'computable': False, 'reason': 'pregnancy_breastfeeding_needs_specialist'}

    # 6. Weight multiplier
    wt = tables['weight']
    if age_years < 18:
        wt_mult = weight_kg / wt['reference_kg']
    elif weight_kg < wt['adult_underweight_thresh_kg']:
        wt_mult = wt['adult_underweight_mult']
    else:
        wt_mult = 1.0

    # 7. Combine
    raw  = base_dose_mid_mg * age_mult * sev_mult * ren_mult * hep_mult * gen_mult * wt_mult
    dose = round(raw, 1)

    # 8. Cap at age-group max
    if age_max is not None:
        dose = min(dose, age_max)

    daily = round(dose * doses_per_day, 1) if doses_per_day else dose

    return {
        'computable':      True,
        'single_dose_mg':  dose,
        'doses_per_day':   doses_per_day,
        'daily_dose_mg':   daily,
        'multipliers': {
            'age':      age_mult,
            'severity': sev_mult,
            'renal':    ren_mult,
            'hepatic':  hep_mult,
            'gender':   gen_mult,
            'weight':   round(wt_mult, 3),
        },
    }

